# Blank

maker: C · with: — · parent: — · session: —

## Pitch

A dot you can steer until the time runs out. Replace all of this with the game.

## Rules

- R1 (auto): Holding a direction moves the dot 2 pixels per frame. It stops at the edges of the screen.
- R2 (auto): A round lasts 1800 frames, and the score goes up by 1 every 60 frames. Then the game-over screen shows.
- R3 (auto): The best score is still there after the game restarts.
- R4 (you check): The dot is easy to see.

## Controls

- Player 1: stick moves the dot.
- START or A: start from the title screen, and go back to it after game over.
- ★ is the cabinet's button; games never use it.

## Look & sound

Dark background, a sky-blue dot. A "win" sound when the round ends.

## Assumptions

- A1: One round, because nothing else is decided yet.

## Changelog

- v1: First version, the blank start.
// @ts-check
// Blank start: title, play, game over, a best score, and a dot to steer. Everything else is yours.
/** @typedef {{ flow: Arcade.Lib.Flow, sc: Arcade.Lib.Score, x: number, y: number, tick: Arcade.Lib.Timer, round: Arcade.Lib.Timer }} State */

const CFG = { speed: 2, roundFrames: 1800, size: 6, top: 10 };

/** @param {Arcade.G} g @param {State} s */
function newGame(g, s) {
  s.sc = g.lib.score.newScore(g, { lives: 1 });
  s.x = g.W / 2;
  s.y = g.H / 2;
  s.tick = g.lib.timers.timer(60, true);
  s.round = g.lib.timers.timer(CFG.roundFrames);
}

/** @type {Arcade.Cart<State>} */
export default {
  init(g) {
    const s = /** @type {State} */ ({ flow: g.lib.flow.newFlow() });
    newGame(g, s);
    return s;
  },

  update(g, s) {
    const { flow, timers, score } = g.lib;
    flow.tick(s.flow);
    if (s.flow.mode !== "play") {
      if (flow.startPressed(g, s.flow)) {
        if (s.flow.mode === "title") newGame(g, s);
        flow.go(s.flow, s.flow.mode === "title" ? "play" : "title");
      }
      return;
    }
    if (g.btn("left")) s.x -= CFG.speed;
    if (g.btn("right")) s.x += CFG.speed;
    if (g.btn("up")) s.y -= CFG.speed;
    if (g.btn("down")) s.y += CFG.speed;
    s.x = Math.max(0, Math.min(g.W - CFG.size, s.x));
    s.y = Math.max(CFG.top, Math.min(g.H - CFG.size, s.y));
    if (timers.tick(s.tick)) score.addPoints(s.sc, 1);
    if (timers.tick(s.round)) {
      score.commit(g, s.sc);
      g.sfx("win");
      flow.go(s.flow, "over");
    }
  },

  draw(g, s) {
    const { fx } = g.lib;
    const c = g.colors;
    g.cls(c.night);
    if (s.flow.mode === "title") {
      const art = fx.title(g, "BLANK", s.sc.best, { color: c.sky }); // draw title art at art.cx, art.cy
      g.circfill(art.cx, art.cy, 12, c.sky);
      return;
    }
    g.rectfill(s.x, s.y, CFG.size, CFG.size, c.sky);
    g.text(`SCORE ${s.sc.score}  BEST ${s.sc.best}`, 2, 1, c.white);
    if (s.flow.mode === "over") fx.banner(g, "GAME OVER", s.sc.newBest ? "NEW BEST!" : `SCORE ${s.sc.score}`);
  },

  probe(g, s) {
    return { W: g.W, H: g.H, top: CFG.top, mode: s.flow.mode, x: s.x, y: s.y, size: CFG.size, score: s.sc.score, best: s.sc.best, left: s.round.left };
  },
};
// @ts-check
/** @type {Arcade.Checks} */
export default {
  async R1(t) {
    const a = await t.bot.start();
    t.bot.eq((await t.bot.hold("right", 10)).x, a.x + 20, "x after holding right 10 frames");
    const end = await t.bot.hold("right down", 200);
    t.bot.eq([end.x, end.y], [end.W - end.size, end.H - end.size], "the bottom-right corner");
    const top = await t.bot.hold("left up", 200);
    t.bot.eq([top.x, top.y], [0, top.top], "the top-left corner");
  },

  async R2(t) {
    const a = await t.bot.start();
    const p = await t.bot.wait(a.left);
    t.bot.eq(p.mode, "over", "mode when the round's 1800 frames are up");
    t.bot.ok(p.score >= 29, `a whole round should score about 30, got ${p.score}`);
  },

  async R3(t) {
    const a = await t.bot.start();
    const end = await t.bot.wait(a.left);
    await t.reset({ keepSave: true });
    const p = await t.probe();
    t.bot.eq([p.mode, p.best], ["title", end.score], "mode and best after a restart");
  },
};
